int ns_fd; // e.g., open("/proc/self/ns/pid", O_RDONLY)
int parent_fd;
int owner_uid;
int ret;

// OPERATION 1: Retrieve file descriptor (FD returned directly)
// Get FD for the immediate parent namespace
parent_fd = ioctl(ns_fd, NS_GET_PARENT, NULL);

// Get FD for the user namespace associated with ns_fd
int user_ns_fd = ioctl(ns_fd, NS_GET_USERNS, 0);

// OPERATION 2: Retrieve metadata (data written to arg pointer)
// Get UID of the owning user namespace
ret = ioctl(ns_fd, NS_GET_OWNER_UID, &owner_uid);

// EPERM commonly occurs if permissions are inadequate
if (ret < 0 && errno == EPERM) {
    // Access denied
}
